const LOCAL_DATA = JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(''), (char) => char.charCodeAt(0))));

const fetchJSON = async (path) => {
  if (window.location.protocol === 'file:' && LOCAL_DATA[path]) return LOCAL_DATA[path];
  try {
    const res = await fetch(path);
    if (!res.ok) throw new Error(`${path} の読み込みに失敗しました`);
    return res.json();
  } catch (error) {
    if (LOCAL_DATA[path]) return LOCAL_DATA[path];
    throw error;
  }
};

const escapeHTML = (value = '') => String(value).replace(/[&<>"]/g, (s) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[s]));
const media = (src, alt) => src ? `<img src="${escapeHTML(src)}" alt="${escapeHTML(alt)}" loading="lazy">` : `<div class="placeholder">写真素材を追加してください</div>`;
const tagList = (items = []) => `<div class="tags">${items.map(s => `<span class="tag">${escapeHTML(s)}</span>`).join('')}</div>`;

const TYPE_LABEL = { own: '自社事業', client: 'クライアントワーク' };
const ROLE_ALL = ['企画', '制作', '運営'];
const isPublished = (p) => (p.status || 'published') === 'published' && p.mainImage;

const projectCard = (p) => `
  <article class="home-project-card reveal-item">
    <a class="home-project-media" href="projects.html#${escapeHTML(p.id)}" aria-label="${escapeHTML(p.title)}の詳細を見る">${media(p.mainImage, p.title)}</a>
    <div class="home-project-caption">
      <p class="project-name-label"><span class="type-badge type-${escapeHTML(p.type)}">${escapeHTML(TYPE_LABEL[p.type] || 'Project')}</span>${escapeHTML((p.roles || []).join('・'))}</p>
      <h3>${escapeHTML(p.title)}</h3>
      <p>${escapeHTML(p.summary || p.description)}</p>
      <a class="text-link arrow-link" href="projects.html#${escapeHTML(p.id)}">詳細を見る <span aria-hidden="true">→</span></a>
    </div>
  </article>`;

const projectIndexCard = (p) => `
  <a class="project-index-card" href="#${escapeHTML(p.id)}" data-type="${escapeHTML(p.type)}">
    <span class="project-index-media">${media(p.mainImage, p.title)}</span>
    <span class="type-badge type-${escapeHTML(p.type)}">${escapeHTML(TYPE_LABEL[p.type] || '')}</span>
    <strong>${escapeHTML(p.title)}</strong>
    <small>${escapeHTML(p.year)}　${escapeHTML((p.areas || []).join(' / '))}</small>
  </a>`;

const journalCard = (j) => `
  <article class="card">
    <a class="card-media" href="journal.html#${escapeHTML(j.id)}">${media(j.mainImage, j.title)}</a>
    <div class="card-body">
      <div class="meta"><span>${escapeHTML(j.year)}</span><span>${escapeHTML(j.status)}</span></div>
      <h3>${escapeHTML(j.title)}</h3>
      <p>${escapeHTML(j.excerpt)}</p>
      ${tagList(j.tags || [])}
    </div>
  </article>`;

const serviceCard = (s) => `
  <article class="service-card reveal-item">
    <span class="service-number">${escapeHTML(s.number)}</span>
    <h3>${escapeHTML(s.title)}</h3>
    <p>${escapeHTML(s.lead || s.text)}</p>
    <a class="text-link arrow-link" href="services.html#${escapeHTML(s.id)}">詳しく見る <span aria-hidden="true">→</span></a>
  </article>`;

const CONTACT_LABEL = { production: '制作を相談する', event: 'イベントを相談する', project: '企画・プロジェクトを相談する', training: '研修・滞在を相談する' };

const projectDetailCard = (p) => {
  const roles = ROLE_ALL.map(r => `<li class="${(p.roles || []).includes(r) ? 'is-on' : ''}">${r}</li>`).join('');
  const info = [
    ['区分', TYPE_LABEL[p.type]],
    ['クライアント', p.type === 'client' ? p.client : ''],
    ['時期', p.year],
    ['場所', p.location]
  ].filter(([, v]) => v).map(([k, v]) => `<div><dt>${k}</dt><dd>${escapeHTML(v)}</dd></div>`).join('');
  const block = (label, text) => text ? `<section class="case-block"><h3>${label}</h3><p>${escapeHTML(text)}</p></section>` : '';
  const gallery = (p.gallery || []).length ? `<div class="case-gallery">${p.gallery.map(src => `<figure>${media(src, p.title)}</figure>`).join('')}</div>` : '';
  const credits = p.credits && Object.keys(p.credits).length ? `<dl class="credit-list">${Object.entries(p.credits).map(([k, v]) => `<dt>${escapeHTML(k)}</dt><dd>${escapeHTML(v)}</dd>`).join('')}</dl>` : '';
  const links = (p.links || []).map(l => {
    const external = /^https?:/.test(l.url);
    return `<a class="text-link arrow-link" href="${escapeHTML(l.url)}"${external ? ' target="_blank" rel="noopener"' : ''}>${escapeHTML(l.label)} <span aria-hidden="true">${external ? '↗' : '→'}</span></a>`;
  }).join('');
  return `
  <article class="project-case reveal-item" id="${escapeHTML(p.id)}" data-type="${escapeHTML(p.type)}">
    <div class="case-hero">${media(p.mainImage, p.title)}</div>
    <div class="case-body">
      <header class="case-head">
        <span class="type-badge type-${escapeHTML(p.type)}">${escapeHTML(TYPE_LABEL[p.type] || '')}</span>
        <h2>${escapeHTML(p.title)}</h2>
        <p class="case-subtitle">${escapeHTML(p.subtitle || '')}</p>
        <p class="lead">${escapeHTML(p.summary || '')}</p>
      </header>
      <aside class="case-meta">
        <dl class="case-info">${info}</dl>
        <div class="case-roles"><p>担当範囲</p><ul>${roles}</ul></div>
      </aside>
      <div class="case-text">
        ${block('背景', p.background)}
        ${block('Cignalsが考えたこと', p.approach)}
        ${(p.deliverables || []).length ? `<section class="case-block"><h3>つくったもの</h3><ul class="case-deliverables">${p.deliverables.map(d => `<li>${escapeHTML(d)}</li>`).join('')}</ul></section>` : ''}
        ${block('結果・その後', p.result)}
        ${credits ? `<section class="case-block"><h3>チーム・クレジット</h3>${credits}</section>` : ''}
        ${links ? `<div class="case-links">${links}</div>` : ''}
      </div>
    </div>
    ${gallery}
    <div class="case-cta"><a class="button arrow-button" href="contact.html?type=${escapeHTML(p.contactType || 'other')}">${escapeHTML(CONTACT_LABEL[p.contactType] || 'この内容で相談する')} <span aria-hidden="true">→</span></a></div>
  </article>`;
};

const journalArticle = (j) => {
  const paragraphs = String(j.body || '').split(/\n\n+/).filter(Boolean).map(p => `<p>${escapeHTML(p)}</p>`).join('');
  const credits = j.credits ? Object.entries(j.credits).map(([k, v]) => `<dt>${escapeHTML(k)}</dt><dd>${escapeHTML(v)}</dd>`).join('') : '';
  return `<article class="journal-article" id="${escapeHTML(j.id)}">
    <div class="journal-hero-media">${media(j.mainImage, j.title)}</div>
    <div class="journal-content">
      <div class="meta"><span>${escapeHTML(j.publishedAt || j.year)}</span><span>${escapeHTML(j.type)}</span></div>
      <h2>${escapeHTML(j.title)}</h2>
      <p class="lead">${escapeHTML(j.excerpt)}</p>
      ${paragraphs}
      ${tagList(j.tags || [])}
      ${credits ? `<dl class="credit-list">${credits}</dl>` : ''}
    </div>
  </article>`;
};

const serviceDetail = (s) => {
  // 専用LPを持つサービスは、それぞれのLPへ誘導する
  const LP_MAP = {
    'training-retreat': { href: 'https://cignals.jp/camp', text: '研修について詳しく見る' },
    'produce': { href: 'produce.html', text: 'プロデュース契約を詳しく見る' }
  };
  const lp = LP_MAP[s.id];
  const btnHref = lp ? lp.href : 'contact.html';
  const btnText = lp ? lp.text : 'この内容で相談する';

  return `
  <article class="service-detail reveal-item" id="${escapeHTML(s.id)}">
    <div class="service-visual">${media(s.image, s.title)}</div>
    <div class="service-detail-body">
      <p class="eyebrow">${escapeHTML(s.number)} / ${escapeHTML(s.en)}</p>
      <h2>${escapeHTML(s.title)}</h2>
      <p class="lead">${escapeHTML(s.lead)}</p>
      <p>${escapeHTML(s.text)}</p>
      <h3>こんな企業・行政へ</h3>
      <ul>${(s.targets || []).map(t => `<li>${escapeHTML(t)}</li>`).join('')}</ul>
      <p class="notice">${escapeHTML(s.price)}</p>
      <a class="button arrow-button" href="${btnHref}">${btnText} <span aria-hidden="true">→</span></a>
    </div>
  </article>`;
};

const mountHome = async () => {
  const [projects, journal, services] = await Promise.all([fetchJSON('data/projects.json'), fetchJSON('data/journal.json'), fetchJSON('data/services.json')]);
  const projectGrid = document.querySelector('#projectGrid');
  const journalGrid = document.querySelector('#journalGrid');
  const serviceGrid = document.querySelector('#serviceGrid');
  const visible = projects.filter(isPublished);
  const featured = [...visible.filter(p => p.featured), ...visible.filter(p => !p.featured)];
  if (projectGrid) projectGrid.innerHTML = featured.slice(0, Number(projectGrid.dataset.limit || featured.length)).map(projectCard).join('');
  if (journalGrid) journalGrid.innerHTML = journal.slice(0, Number(journalGrid.dataset.limit || journal.length)).map(journalCard).join('');
  if (serviceGrid) serviceGrid.innerHTML = services.map(serviceCard).join('');
};

const mountProjects = async () => {
  const projects = (await fetchJSON('data/projects.json')).filter(isPublished);
  const grid = document.querySelector('#projectGrid');
  const index = document.querySelector('#projectIndex');
  grid.innerHTML = projects.map(projectDetailCard).join('');
  if (index) index.innerHTML = projects.map(projectIndexCard).join('');
  const buttons = document.querySelectorAll('.project-filter button');
  const apply = (type) => {
    buttons.forEach(b => { const on = b.dataset.filter === type; b.classList.toggle('is-active', on); b.setAttribute('aria-pressed', String(on)); });
    document.querySelectorAll('.project-case, .project-index-card').forEach(el => { el.hidden = type !== 'all' && el.dataset.type !== type; });
  };
  buttons.forEach(b => b.addEventListener('click', () => apply(b.dataset.filter)));
  // 縦長のポスターなどは切り取らずに全体を見せる
  document.querySelectorAll('.case-gallery img').forEach(img => {
    const mark = () => { if (img.naturalHeight > img.naturalWidth * 1.05) img.closest('figure').classList.add('is-portrait'); };
    img.complete ? mark() : img.addEventListener('load', mark, { once: true });
  });
  // ハッシュで直接開いたとき、描画後に該当の実績へスクロールする
  if (location.hash) {
    const target = document.getElementById(decodeURIComponent(location.hash.slice(1)));
    if (target) setTimeout(() => target.scrollIntoView({ block: 'start' }), 60);
  }
};

const mountJournal = async () => {
  const journal = await fetchJSON('data/journal.json');
  document.querySelector('#journalArticleList').innerHTML = journal.map(journalArticle).join('');
};

const mountServices = async () => {
  const list = document.querySelector('#serviceDetailList');
  if (!list) return; // 2026-10 リニューアル以降、ServicesページはHTMLに直接記述
  const services = await fetchJSON('data/services.json');
  list.innerHTML = services.map(serviceDetail).join('');
};

const mountContact = () => {
  const form = document.querySelector('#contactForm');
  const thanks = document.querySelector('#formThanks');
  if (!form) return;
  // ssgform へ POST するためフォームのデフォルト送信をそのまま使用
  // （event.preventDefault() / mailto: は使わない）
  // ?type=production などで相談内容を選択済みにする
  const select = document.querySelector('#contactType');
  const choose = (key) => {
    if (!select || !key) return;
    const opt = Array.from(select.options).find(o => o.dataset.key === key);
    if (opt) select.value = opt.value;
    document.querySelectorAll('.contact-menu-links a').forEach(a => a.classList.toggle('is-active', a.dataset.type === key));
  };
  choose(new URLSearchParams(location.search).get('type'));
  document.querySelectorAll('.contact-menu-links a').forEach(a => a.addEventListener('click', (e) => {
    e.preventDefault(); choose(a.dataset.type); form.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }));
  select?.addEventListener('change', () => choose(select.selectedOptions[0]?.dataset.key));
};

const initMotion = () => {
  document.querySelectorAll('.card, .home-project-card, .project-detail, .service-card, .service-detail, .place-card, .values-grid article, .member-grid article, .area-card, .engage-grid article, .base-grid article').forEach((el) => {
    el.classList.add('motion-card');
  });

  const revealTargets = Array.from(document.querySelectorAll('.section, .page-hero, .hero, .cta, .motion-card, .reveal-item'));
  if (!('IntersectionObserver' in window)) {
    revealTargets.forEach((el) => el.classList.add('is-visible'));
    return;
  }

  const observer = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      if (entry.isIntersecting || entry.intersectionRatio > 0) {
        entry.target.classList.add('is-visible');
        observer.unobserve(entry.target);
      }
    });
  }, {
    // 画面より縦長の要素（サービス一覧セクション等）でも必ず発火するよう
    // threshold は 0 を含める。0.12 だと画面高を超える要素は永久に条件を満たさない。
    rootMargin: '0px 0px -5% 0px',
    threshold: 0
  });
  revealTargets.forEach((el) => observer.observe(el));

  // フォールバック：Observerが取りこぼした要素を、画面に重なった時点で強制表示
  const failsafe = () => {
    const vh = window.innerHeight;
    revealTargets.forEach((el) => {
      if (el.classList.contains('is-visible')) return;
      const r = el.getBoundingClientRect();
      // 画面と少しでも重なっていれば表示（縦長要素にも対応）
      if (r.top < vh && r.bottom > 0) {
        el.classList.add('is-visible');
        observer.unobserve(el);
      }
    });
  };
  window.addEventListener('scroll', failsafe, { passive: true });
  window.addEventListener('resize', failsafe, { passive: true });
  window.addEventListener('load', failsafe);
  failsafe();
  setTimeout(failsafe, 300);
};

const initFaqAccordion = () => {
  document.querySelectorAll(".faq-list article").forEach((article) => {
    article.addEventListener("click", () => {
      article.classList.toggle("is-open");
    });
  });
};
/* ===== TimeRex予約ボタンのクリックをGA4イベントとして計測 ===== */
const initReservationTracking = () => {
  document.querySelectorAll('a[href*="timerex.net"]').forEach((link) => {
    link.addEventListener('click', () => {
      if (typeof window.gtag === 'function') {
        window.gtag('event', 'reservation_click', {
          location: link.dataset.cta || 'unknown',
          page: document.body.dataset.page || 'home'
        });
      }
    });
  });
};

const init = async () => {
  const page = document.body.dataset.page || 'home';
  if (page === 'home') await mountHome();
  if (page === 'projects') await mountProjects();
  if (page === 'journal') await mountJournal();
  if (page === 'services') await mountServices();
  if (page === 'contact') mountContact();
  initMotion();
  initFaqAccordion();
  initTypewriter();
  initHamburger();
  initReservationTracking();
};


/* ===== Typewriter: Home About Section ===== */
const initTypewriter = () => {
  const section = document.getElementById('home-about');
  if (!section) return;

  const paras = section.querySelectorAll('.typewriter-para');
  if (!paras.length) return;

  // 各段落のテキストをspanに分解
  paras.forEach((para) => {
    const raw = para.innerHTML
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>');
    para.innerHTML = '';
    [...raw].forEach((ch) => {
      if (ch === '\n') {
        para.appendChild(document.createElement('br'));
      } else {
        const span = document.createElement('span');
        span.className = 'typewriter-char';
        span.textContent = ch;
        para.appendChild(span);
      }
    });
  });

  // カーソル要素
  const cursor = document.createElement('span');
  cursor.className = 'typewriter-cursor';

  let started = false;

  const startTyping = () => {
    if (started) return;
    started = true;
    section.classList.add('typewriter-started');

    const allChars = Array.from(section.querySelectorAll('.typewriter-char'));
    const BASE_SPEED = 28; // ms/char
    const PARA_PAUSE = 320; // ms between paragraphs

    let delay = 0;
    let lastPara = null;

    allChars.forEach((span, i) => {
      const para = span.closest('.typewriter-para');
      if (para !== lastPara) {
        if (lastPara !== null) delay += PARA_PAUSE;
        lastPara = para;
      }
      const d = delay;
      setTimeout(() => {
        span.classList.add('visible');
        // カーソルを現在の文字の後ろに移動
        span.after(cursor);
        // 最後の文字のあとカーソルを消す
        if (i === allChars.length - 1) {
          setTimeout(() => cursor.remove(), 1800);
        }
      }, d);
      delay += BASE_SPEED + Math.random() * 14;
    });
  };

  // IntersectionObserver でビューポートに入ったら開始
  const observer = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          startTyping();
          observer.disconnect();
        }
      });
    },
    { threshold: 0.25 }
  );
  observer.observe(section);
};

/* ===== Hamburger Menu ===== */
const initHamburger = () => {
  const toggle = document.querySelector('.nav-toggle');
  const nav = document.querySelector('#primaryNav');
  if (!toggle || !nav) return;

  toggle.addEventListener('click', () => {
    const isOpen = nav.classList.toggle('is-open');
    toggle.setAttribute('aria-expanded', String(isOpen));
    toggle.setAttribute('aria-label', isOpen ? 'メニューを閉じる' : 'メニューを開く');
  });

  // ナビリンクをタップしたらメニューを閉じる
  nav.querySelectorAll('a').forEach((a) => {
    a.addEventListener('click', () => {
      nav.classList.remove('is-open');
      toggle.setAttribute('aria-expanded', 'false');
      toggle.setAttribute('aria-label', 'メニューを開く');
    });
  });

  // メニュー外タップで閉じる
  document.addEventListener('click', (e) => {
    if (!toggle.contains(e.target) && !nav.contains(e.target)) {
      nav.classList.remove('is-open');
      toggle.setAttribute('aria-expanded', 'false');
      toggle.setAttribute('aria-label', 'メニューを開く');
    }
  });
};

// 関数定義がすべて読み込まれてから初期化する（const 関数の参照前エラーを防ぐ）
init().catch((error) => {
  console.error(error);
  document.body.insertAdjacentHTML('beforeend', `<p style="padding:24px;color:#eb0034">${escapeHTML(error.message)}</p>`);
});
